using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Informs the user who some of the elements in their Telegram Passport contain errors; for bots only. The user will not be able to resend the elements, until the errors are fixed
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetPassportElementErrorsAsync(long userId = default, InputPassportElementError[] errors = default)
    {

           using var activity =  StartCallActivity("SetPassportElementErrorsAsync", typeof(SetPassportElementErrors).FullName ?? "SetPassportElementErrorsAsync");

           try
           {
             return client.SetPassportElementErrorsAsync(userId, errors);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
